export class Player {
  constructor() {
    this.position = { x: 0, y: 0.5, z: 0 };
    this.velocity = { x: 0, y: 0, z: 0 };

    this.color = "#00ff88";
    this.scale = 1;

    this.speed = 5;
    this.jumpPower = 8;
    this.gravity = 20;

    this.health = 20;
    this.onGround = false;
  }

  update(deltaTime, input) {
    // Movement
    if (input.forward) this.velocity.z = -this.speed;
    else if (input.back) this.velocity.z = this.speed;
    else this.velocity.z = 0;

    if (input.left) this.velocity.x = -this.speed;
    else if (input.right) this.velocity.x = this.speed;
    else this.velocity.x = 0;

    // Gravity
    this.velocity.y -= this.gravity * deltaTime;

    // Jump
    if (input.jump && this.onGround) {
      this.velocity.y = this.jumpPower;
      this.onGround = false;
    }

    // Apply velocity
    this.position.x += this.velocity.x * deltaTime;
    this.position.y += this.velocity.y * deltaTime;
    this.position.z += this.velocity.z * deltaTime;

    // Simple ground collision
    if (this.position.y < 0.5) {
      this.position.y = 0.5;
      this.velocity.y = 0;
      this.onGround = true;
    }
  }
}

